#pragma once
#include <stdint.h>

namespace vamc {

enum class PairingMethod : uint8_t {
    JUST_WORKS,
    PASSKEY,
    NUMERIC_COMPARISON
};

enum class PairingState : uint8_t {
    IDLE,
    AWAITING_HOST_CONFIRMATION,
    PAIRED,
    REJECTED
};

// Implementations belong to the setup page and the chosen BLE stack. The
// passkey must be generated by a suitable provider outside this module.
class PairingPresentation {
public:
    virtual ~PairingPresentation() = default;
    // Display as six digits, preserving leading zeroes.
    virtual bool show_passkey(uint32_t passkey) = 0;
    virtual void clear_passkey() = 0;
};

class PairingRadio {
public:
    virtual ~PairingRadio() = default;
    virtual bool begin_passkey_pairing(uint32_t passkey) = 0;
    virtual void erase_untrusted_bond() = 0;
};

class AuthenticatedPairing {
public:
    AuthenticatedPairing(PairingPresentation& presentation, PairingRadio& radio)
        : presentation_(presentation), radio_(radio), state_(PairingState::IDLE) {}

    bool begin(uint32_t passkey);
    void on_host_result(bool bonded, PairingMethod method);
    PairingState state() const { return state_; }

private:
    PairingPresentation& presentation_;
    PairingRadio& radio_;
    PairingState state_;
};

} // namespace vamc
